-- Developmental_Care 초기 데이터 삽입 (검수 완료 버전)
-- 생성일: 2026-06-02
-- 총 61개 항목: 생후 4개월~36개월

SET NAMES utf8mb4;

INSERT INTO Developmental_Care
  (id, type, age_months, age_weeks, age_label, wonder_weeks_leap, is_sleep_regression,
   dev_status, sleep_activities, vaccination, separation_sleep_guide)
VALUES
  (1, 'weekly', 4, 16, '생후 16주 (4개월)', NULL, 1, '이 시기 아기는 배밀이 자세에서 팔꿈치로 몸을 지탱하며 고개를 45~90도 들어올릴 수 있어요. 손을 입으로 가져가 탐색하고, 눈앞 물체를 향해 손을 뻗기 시작합니다. 수면 구조가 신생아형에서 성인형으로 영구 전환되는 시기로, 낮잠이 갑자기 짧아지거나 밤잠이 자주 깨지는 4개월 수면 퇴행이 시작될 수 있습니다.', '["배밀이(Tummy Time) 10~15분: 팔·목 근육 사용으로 낮 시간 에너지를 충분히 소모시켜 밤잠에 도움","딸랑이·모빌 따라보기: 시선 추적과 팔 뻗기 연습으로 인지 자극 후 피로 유도","목욕 후 베이비 오일 마사지 5분: 체온 하강을 유도해 수면 진입을 쉽게 해줌"]', '이달 국가필수예방접종: DTaP(디프테리아·파상풍·백일해) 2차, IPV(소아마비) 2차, Hib(뇌수막염) 2차, PCV(폐렴구균) 2차, 로타바이러스 2차. 접종 당일은 무리한 활동을 피하고 접종 후 15~30분 의료기관에서 관찰하세요.', '4개월은 분리수면 준비를 시작하기 좋은 첫 시점이에요. 수면 구조가 성인형으로 바뀌는 이 시기부터 Drowsy But Awake(졸리지만 눈 뜬 상태로 눕히기) 원칙을 낮잠부터 천천히 연습해보세요.'),
  (2, 'weekly', 4, 17, '생후 17주 (4개월 1주)', NULL, 1, '뒤집기를 준비하는 시기로, 옆으로 몸을 굴리려는 시도가 활발해져요. 수면 중에도 뒤집으려 힘쓰다 잠에서 깰 수 있습니다. 4개월 수면 퇴행이 진행 중이라면 낮잠 길이가 20~30분으로 짧아지는 것이 정상이에요.', '["유도 뒤집기 연습: 옆으로 살짝 굴려주는 도움 동작으로 대근육 발달 자극","아기 체육관(플레이짐) 누워서 놀기: 팔 뻗기·다리 차기로 에너지 소모","조용한 자장가 + 일관된 수면 신호: 짧아진 낮잠에 맞춰 루틴 일관성 유지"]', '이 주 정기 접종 없음. 지난주 4개월 접종을 아직 받지 않으셨다면 이번 주 소아과 방문을 권장합니다.', '수면 퇴행으로 분리수면이 어렵게 느껴질 수 있어요. 하지만 이 시기에 Drowsy But Awake 원칙을 포기하지 마세요. 퇴행은 2~6주 내 자연스럽게 회복됩니다.'),
  (3, 'weekly', 4, 18, '생후 18주 (4개월 2주)', 4, 1, '원더윅스 도약 4(19주)가 임박한 시기예요. 아기가 평소보다 더 보채거나 수유량이 늘고, 잠들기 어려워하는 예고 증상이 나타날 수 있습니다. 이 도약은 원인과 결과를 이해하는 ''사건의 세계'' 열림으로, 뇌가 빠르게 성장하고 있다는 신호예요.', '["반복 원인-결과 장난감: 버튼을 누르면 소리가 나는 장난감으로 인지 자극 (낮 시간)","까꿍 놀이(Peek-a-Boo): 대상 영속성 자극 + 웃음으로 낮 스트레스 해소","취침 루틴 일관성 강화: 목욕→수유→자장가 순서를 동일하게 유지해 뇌 도약 중 안정감 제공"]', '이 주 정기 접종 없음.', '도약 직전에는 보채기와 야간 각성이 일시적으로 심해질 수 있어요. 지금 분리수면을 새로 시작하기보다는 기존 루틴 유지에 집중하고, 도약이 안정된 후 시도하세요.'),
  (4, 'weekly', 4, 19, '생후 19주 (약 4.5개월) ★원더윅스 도약 4', 4, 1, '원더윅스 도약 4 피크 시기예요. 아기의 뇌가 ''원인과 결과(사건의 세계)''를 이해하기 시작하며, 딸랑이를 의도적으로 흔들어 소리를 만드는 등 새로운 능력이 생겨나고 있습니다. 이 시기는 보채기·야간 각성·낮잠 거부가 흔하고 1~6주간 지속될 수 있어요.', '["원인-결과 장난감 탐색 (낮 15분): 인지 도약에 맞는 자극으로 낮 에너지 충분히 사용","자연 산책 (유모차 30분): 신선한 공기와 시각 자극이 뇌 도약 중 각성을 조절하는 데 도움","취침 전 화이트노이즈 + 어두운 환경: 뇌 자극이 많은 시기일수록 수면 환경을 더 조용하게"]', '이 주 정기 접종 없음.', '도약 4 중에는 분리수면 시도를 잠시 미루거나, 이미 하고 계신다면 일관성만 유지하세요. 도약이 끝나면(보통 1~6주 후) 오히려 수면이 안정될 수 있습니다.'),
  (5, 'weekly', 5, 20, '생후 20주 (5개월)', 4, 0, '도약 4가 마무리되며 아기가 한결 편안해 보일 수 있어요. 뒤집기(배→등)가 완성되거나 완성에 가까워지며, 두 손으로 장난감을 잡아 탐색하는 능력이 향상됩니다. 낮잠이 조금 길어지고 밤잠이 안정되기 시작할 수 있어요.', '["뒤집기 응원 놀이: 배밀이 후 스스로 뒤집으면 칭찬과 박수로 강화, 대근육 발달 촉진","두 손 장난감 잡기: 블록이나 링 장난감 두 개를 주어 양손 협응 연습","저녁 목욕 + 마사지 루틴: 도약 후 안정기를 활용해 일관된 취침 루틴 강화"]', '이 주 정기 접종 없음. 다음 접종: 6개월 (DTaP 3차, IPV 3차, Hib 3차, PCV 3차, HepB 3차, 인플루엔자).', '도약 4가 지나며 수면이 안정되기 시작하는 시기예요. Drowsy But Awake 원칙이 자리잡기 좋은 때입니다. 낮잠 1회를 혼자 재우는 것부터 시작해보세요.'),
  (6, 'weekly', 5, 21, '생후 21주 (5개월 1주)', NULL, 0, '이 시기 아기는 뒤집기를 자유자재로 하며, 엎드린 자세에서 팔을 곧게 펴고 오랫동안 버티기 시작해요. 소리가 나는 쪽으로 고개를 돌리고, 친숙한 목소리와 낯선 목소리를 구별합니다. 수유 패턴이 조금씩 규칙적으로 잡히면서 수면 리듬도 함께 안정될 수 있어요.', '["소리 탐색 놀이: 딸랑이를 여러 방향에서 흔들어 청각 발달 + 고개 돌리기 연습","거울 탐색: 거울 앞에서 자기 모습을 보며 표정 탐색, 사회성 발달 자극","낮잠 전 짧은 안기 루틴: 낮잠 20분 전부터 조용한 환경 조성"]', '이 주 정기 접종 없음.', '5개월은 분리수면 연습을 이어가기 좋은 시기예요. 아직 4개월 수면 퇴행 여파가 있다면 조급해하지 말고, 낮잠 1~2회 혼자 재우기를 목표로 하세요.'),
  (7, 'weekly', 5, 22, '생후 22주 (5개월 2주)', NULL, 0, '손가락 전체로 물건을 쥐는 능력이 발달하고, 이유식 시작을 준비하는 시기예요. 아기가 식탁 음식을 눈으로 쫓거나 군침을 흘리기 시작한다면 이유식 준비 신호일 수 있습니다. 낮 수유 간격이 길어지면서 밤중 수유 횟수가 조금 줄기 시작해요.', '["식감 탐색 바구니: 부드러운·거친·차가운 재질의 안전 물건을 담은 바구니로 촉감 발달","옹알이 대화 놀이: 아기 소리를 따라 하며 주고받는 대화 연습, 정서 안정에 도움","저녁 목욕 후 수유→졸음→눕히기 순서 연습: Sleep Prop 없는 수면 연상 형성"]', '이 주 정기 접종 없음.', '밤중 수유가 조금씩 줄어드는 시기예요. 밤중 각성 시 바로 수유하기보다 잠시 기다려보는 연습도 분리수면 준비에 도움이 됩니다.'),
  (8, 'weekly', 5, 23, '생후 23주 (5개월 3주)', NULL, 0, '6개월에 가까워지며 혼자 앉기 연습을 시작해요. 아직 등이 구부정하게 무너지지만 짧은 시간 버티기가 가능합니다. 이유식을 시작했다면 새로운 맛과 질감 탐색으로 낮 활동이 더 풍부해져 밤잠에 도움이 될 수 있어요.', '["앉기 보조 연습: 양쪽에서 쿠션으로 지지하며 잠깐 앉히기, 코어 근육 발달","물체 건네기 놀이: 장난감을 양손 사이에서 옮기기 연습, 눈-손 협응 발달","취침 1시간 전 조명 어둡게: 멜라토닌 분비 유도로 자연스러운 수면 준비"]', '이 주 정기 접종 없음. 다음 주 6개월 접종 예약을 준비하세요 (DTaP 3차, IPV 3차, Hib 3차, PCV 3차, HepB 3차, 인플루엔자).', '6개월이 되면 분리수면을 본격적으로 시작하기 좋은 시기예요. 밤잠 분리수면을 준비하고 계신다면 취침 루틴을 일관되게 만들어두는 것이 중요합니다.'),
  (9, 'weekly', 6, 24, '생후 24주 (6개월)', NULL, 0, '이 시기 아기는 뒤집기를 완벽히 하고, 두 손으로 지탱하며 앉기 시작해요. 소리 내어 웃고, 친숙한 사람을 보면 환하게 웃으며 반응합니다. 이유식을 시작하는 시기로, 새로운 맛 탐색과 앉아서 먹는 경험이 낮 활동을 풍부하게 합니다.', '["앉아서 블록 쌓기·두드리기: 앉기 균형 연습 + 양손 협응으로 충분한 에너지 소모","이유식 후 감각 놀이: 이유식 후 짧은 탐색 놀이로 \u0027먹기→놀기→자기(EASY 루틴)\u0027 형성","목욕 + 마사지 + 수유 루틴 고정: 6개월부터 일관된 취침 루틴이 수면 독립의 핵심"]', '이달 국가필수예방접종: DTaP 3차, IPV 3차, Hib 3차, PCV 3차, HepB 3차(마지막), 로타바이러스 3차(로타텍 기준), 인플루엔자 1차(첫해는 4주 후 2차 추가). 이달 접종이 가장 많은 달이니 가능하면 하루에 나눠 맞추는 것도 고려하세요.', '6개월은 분리수면을 시작하기 가장 좋은 시기예요. 야간 수유 없이 잠들 수 있는 체중이 되고, 수면 리듬이 안정됩니다. 퍼버법 또는 의자법으로 점진적으로 접근해보세요.'),
  (10, 'weekly', 6, 25, '생후 25주 (6개월 1주) ★원더윅스 도약 5 시작', 5, 0, '원더윅스 도약 5(관계의 세계)가 시작되는 시기예요. 아기가 물건 간의 관계를 이해하기 시작합니다. ''장난감이 상자 안에 있다'', ''엄마가 문 뒤로 사라졌다가 돌아온다'' 같은 공간적 관계를 인식하기 시작하며 대상 영속성이 심화됩니다.', '["물건 숨기기 놀이: 천으로 장난감을 덮었다 보여주기, 대상 영속성 강화 + 분리불안 완화","컵에 물건 넣고 빼기: 관계의 세계 도약에 맞는 탐색 활동","취침 전 화이트노이즈 사용: 도약 중 자극에 민감해진 신경계를 안정시켜 입면 시간을 단축"]', '이 주 정기 접종 없음. 인플루엔자 첫해 접종자는 1차 후 4주에 2차 접종 예약 확인.', '도약 5로 분리불안이 시작될 수 있어요. 아기가 부모가 없어진다는 것을 인식하게 되면서 취침 시 울음이 늘 수 있습니다. 까꿍 놀이로 낮에 ''사라졌다 돌아온다''는 영속성을 충분히 연습해주세요.'),
  (11, 'weekly', 6, 26, '생후 26주 (약 6개월) ★원더윅스 도약 5 피크', 5, 0, '원더윅스 도약 5 피크예요. 대상 영속성이 뚜렷해지며 엄마·아빠가 없어지면 찾기 시작하고, 낯선 사람에 대한 경계심이 생깁니다. 혼자 잘 앉고, 발가락을 손으로 잡거나 입으로 가져가 탐색해요.', '["오전 신선한 공기 산책 (20~30분): 자연광 노출로 일주기 리듬(서카디안 리듬) 강화","상자 탐색 놀이: 크기 다른 상자에 물건 넣고 꺼내기, 관계의 세계 도약 맞춤 활동","취침 루틴에 \u0027굿나잇 인사\u0027 추가: 분리불안 시작 시기에 일관된 작별 의식이 안정감 제공"]', '이 주 정기 접종 없음.', '도약 5 중 분리불안으로 밤잠에 더 울 수 있어요. 분리수면 중이라면 일관성을 유지하는 것이 가장 중요합니다. 포기하지 말고 같은 방식으로 반응해주세요.'),
  (12, 'weekly', 6, 27, '생후 27주 (6개월 3주) ★원더윅스 도약 5 마무리', 5, 0, '도약 5가 마무리되면서 아기가 한결 밝아지고 새로운 능력이 눈에 띄기 시작해요. 두 손에 물건을 동시에 잡고, 한 손에서 다른 손으로 옮기는 것이 가능해집니다. 옹알이가 더 다양해지고 길어집니다.', '["양손 물건 전달 놀이: 한 손에서 다른 손으로 물건 전달 연습, 소근육 발달","음악에 맞춰 무릎 위에서 흔들기: 리듬감 발달 + 정서적 유대 강화","낮잠 2회 고정 루틴: 오전·오후 낮잠 시간 일관성 유지로 밤잠 준비"]', '이 주 정기 접종 없음. 다음 정기 접종: 12~15개월 (MMR, 수두, Hib, PCV, A형간염, 일본뇌염).', '도약 5가 끝나면 분리수면이 조금 수월해질 수 있어요. 이 시기에 본격적으로 밤잠 분리수면을 시도하기 좋습니다.'),
  (13, 'weekly', 7, 28, '생후 28주 (7개월)', NULL, 0, '이 시기 아기는 혼자 안정적으로 앉을 수 있어요. 집게손가락으로 물건을 가리키거나 긁어 모으는 레이크 그라스프가 발달합니다. 이유식이 안정되며 낮 수유가 줄고 밤 수유가 1~2회로 정리될 수 있어요.', '["앉아서 장난감 두드리기: 앉기 균형과 양손 협응 동시 훈련, 충분한 에너지 소모","질감 탐색 바구니: 부드러운·거친·딱딱한 안전 물건들 탐색으로 감각 발달","저녁 목욕 시간 고정 (오후 7시 전후): 체온 하강 유도로 입면 용이"]', '이 주 정기 접종 없음.', '7개월은 분리수면을 이미 시작했다면 꾸준히 이어가기 좋은 시기예요. 아직 시작 못 하셨다면 지금도 좋습니다. 밤중 수유가 1~2회라면 퍼버법 시도를 고려해보세요.'),
  (14, 'weekly', 7, 29, '생후 29주 (7개월 1주)', NULL, 0, '기어가기 준비 단계로, 엎드린 자세에서 무릎을 배 아래로 가져오려는 시도가 보여요. 넘어져도 손으로 지탱하는 반응이 발달합니다. 점점 이동하려는 욕구가 강해지면서 수면 중에도 자세를 바꾸려다 잠에서 깰 수 있어요.', '["안전한 바닥 이동 공간 마련: 기어가기 준비를 위한 충분한 활동 공간 확보","터널 크롤링: 빈 박스로 만든 터널 통과 놀이로 기어가기 연습 자극","취침 전 부드러운 스트레칭: 발달 근육 이완으로 편안한 수면 유도"]', '이 주 정기 접종 없음.', '기어가기를 시작하면 밤에도 연습하느라 수면이 분절될 수 있어요. 이는 발달 이슈이므로 일관된 루틴 유지가 최선입니다.'),
  (15, 'weekly', 7, 30, '생후 30주 (7개월 2주)', NULL, 0, '아기가 자기 이름에 반응하기 시작하고, 낯선 사람을 보면 경계하는 낯가림이 본격화될 수 있어요. ''마마'', ''바바'' 같은 의미 없는 이중 음절 옹알이가 활발해집니다. 낮잠이 2회로 정착하는 시기예요.', '["이름 부르기 게임: \u0027○○야, 이리 와!\u0027 하고 팔을 벌리기, 청각 반응과 이동 욕구 자극","공 굴리기 주고받기: 앉은 자세에서 공 굴리기로 협응력 발달","낮잠 2회 일정 고정: 오전 9~10시, 오후 1~2시 낮잠 루틴 유지"]', '이 주 정기 접종 없음.', '낯가림이 심해지면 취침 시 울음도 늘 수 있어요. 취침 루틴의 마지막을 항상 같은 사람이 같은 방식으로 하는 것이 불안을 줄이는 데 도움됩니다.'),
  (16, 'weekly', 7, 31, '생후 31주 (7개월 3주)', NULL, 0, '기어가기가 시작되거나 임박한 시기예요. 배로 밀기에서 네 발 자세 잡기로 발전하고, 가구를 잡고 일어서려는 시도가 보이기 시작합니다. 이동 능력이 생기면서 수면 중 이동·자세 변화로 인한 각성이 늘 수 있어요.', '["기어가기 장거리 코스: 쿠션·장난감 배치로 기어가며 탐색하는 코스 만들기","서기 연습 (가구 잡기): 안전한 소파나 테이블 가장자리 잡고 일어서기 도움","잠자리 환경 점검: 기어다니며 더워질 수 있으니 수면 중 실내 온도 18~22°C 유지 확인"]', '이 주 정기 접종 없음.', '이 시기 분리수면을 처음 시작하신다면 퍼버법(3분→5분→10분 간격 체크인)이 효과적이에요. 일관성을 3~7일 이상 유지해야 효과가 나타납니다.'),
  (17, 'weekly', 8, 32, '생후 32주 (8개월)', NULL, 0, '기어가기가 활발해지고 가구를 잡고 서기를 시도해요. 양손에 물건을 들고 두드리는 것을 좋아하며, 떨어진 물건을 스스로 찾습니다(대상 영속성 완성). 8개월 수면 퇴행이 시작될 수 있는 시기입니다.', '["기어가기 장애물 코스: 쿠션 위 넘기, 아래 통과하기로 전신 운동","블록 두드리기: 양손에 블록 들고 두드리기, 청각 자극 + 협응 발달","취침 전 에너지 수준 확인: 기어다니느라 과도하게 흥분되지 않도록 취침 1시간 전 조용한 활동으로 전환"]', '이 주 정기 접종 없음.', '8개월은 분리불안과 대운동 발달이 동시에 폭발하는 시기예요. 분리수면 중이라면 흔들리지 말고 일관성 유지가 핵심입니다.'),
  (18, 'weekly', 8, 33, '생후 33주 (8개월 1주)', NULL, 1, '8~10개월 수면 퇴행이 시작될 수 있어요. 기기·서기 등 대운동 발달과 분리불안(영속성 개념 발달)이 동시에 폭발하면서 수면에 영향을 줍니다. 이미 수면 교육이 된 아기도 야간 각성이 늘 수 있어요.', '["낮 충분한 기어가기·서기 연습: 대근육 에너지를 낮에 충분히 소모시켜 밤 수면 깊이 확보","까꿍 놀이 집중: \u0027사라졌다 돌아온다\u0027 영속성 반복 강화로 분리불안 완화","취침 루틴에 \u0027굿나잇 여행\u0027 추가: 방을 돌며 물건들에게 굿나잇 인사하는 일관된 의식"]', '이 주 정기 접종 없음.', '8개월은 분리수면을 처음 시작하기 가장 어려운 시기예요. 이미 시도 중이라면 일관성 유지가 핵심. 처음 시작하신다면 의자법(Chair Method)이 분리불안 아기에게 특히 적합합니다.'),
  (19, 'weekly', 8, 34, '생후 34주 (8개월 2주)', NULL, 1, '가구를 잡고 서기(풀투스탠드)가 발달하고, 서 있다가 앉는 방법을 배우려 해요. 밤에도 서기 연습을 하다 혼자 눕지 못해 우는 경우가 생길 수 있습니다. 분리불안도 함께 심화됩니다.', '["서기→앉기 반복 연습 (낮): 안전하게 혼자 앉는 법을 낮에 충분히 연습","인형 포옹 놀이: 인형에게 \u0027굿나잇\u0027하는 흉내 놀이로 취침 루틴 자연스럽게 학습","취침 시 혼자 눕는 연습: 서다가 혼자 앉을 수 있으면 수면 중 각성 시 울음 감소"]', '이 주 정기 접종 없음.', '밤에 서다 못 눕는 경우, 단호하지만 따뜻하게 눕혀주고 즉시 자리를 비워주는 방식이 효과적이에요. 안아 올리면 일어서기 반복 패턴이 될 수 있습니다.'),
  (20, 'weekly', 8, 35, '생후 35주 (8개월 3주)', NULL, 1, '서 있는 상태에서 한 발을 옆으로 옮기는 크루징(가구 잡고 이동)이 시작될 수 있어요. 손가락과 엄지로 물건을 집는 집게 잡기(pincer grasp)가 발달합니다. 수면 퇴행이 진행 중이라면 기존 루틴을 흔들지 않는 것이 가장 중요해요.', '["크루징 연습: 소파나 책장 가장자리를 잡고 옆으로 이동 유도","콩·쌀 탐색 놀이 (안전 감독 하): 집게 잡기 발달에 맞는 소근육 자극","퇴행 중 루틴 강화: 평소보다 취침 30분 일찍 시작해 Overtired 방지"]', '이 주 정기 접종 없음.', '수면 퇴행 중에는 새로운 수면 교육법 시작을 자제하세요. 이미 하고 계신 방법을 일관되게 유지하면 2~4주 내 회복됩니다.'),
  (21, 'weekly', 9, 36, '생후 36주 (9개월) ★원더윅스 도약 6 시작', 6, 1, '원더윅스 도약 6(범주의 세계)이 시작돼요. 아기는 물건을 종류·크기·색깔로 분류하기 시작하며 세상을 그룹으로 인식합니다. ''개'' = 코, 꼬리, 발이 있는 것이라는 범주 개념이 생겨요. 9개월 발달 이정표로 가구 잡고 이동(크루징)이 활발해집니다.', '["분류 바구니 놀이: 큰 것·작은 것, 부드러운 것·딱딱한 것 나누기 — 범주 세계 도약 맞춤","야외 자연 관찰: 강아지, 고양이, 새 등 실물 범주 경험으로 인지 자극","취침 전 \u0027오늘 뭘 봤지?\u0027 짧은 대화: 낮 경험을 정리해주는 루틴으로 안정감 제공"]', '이 주 정기 접종 없음.', '도약 6과 8~10개월 퇴행이 겹쳐 분리수면이 가장 어려운 시기 중 하나예요. 흔들리더라도 루틴을 유지하는 것이 장기적으로 가장 빠른 길입니다.'),
  (22, 'weekly', 9, 37, '생후 37주 (약 9개월) ★원더윅스 도약 6 피크', 6, 1, '도약 6 피크 시기예요. 아기가 ''강아지는 짖는다'', ''컵에는 물이 담긴다'' 같은 범주 특성을 이해하기 시작합니다. 낯선 사람에 대한 경계가 더욱 강해지고, 부모와의 분리에 더 민감해져요.', '["동물 소리 책: 동물 이름과 소리를 연결하는 범주 학습 — 취침 전 루틴에 포함 가능","크루징 장거리 코스: 소파→테이블→책상 연결 경로로 충분한 이동 에너지 소모","취침 전 포옹 충분히: 분리불안이 심한 시기일수록 낮 접촉을 충분히 해 취침 시 분리 저항↓"]', '이 주 정기 접종 없음.', '도약 중에는 취침 시 더 오래 울 수 있어요. 체크인 간격을 평소보다 조금 짧게 (3분→5분으로) 조정하는 것도 방법입니다. 단, 방법을 매일 바꾸는 것은 더 혼란스럽습니다.'),
  (23, 'weekly', 9, 38, '생후 38주 (9개월 2주) ★원더윅스 도약 6 마무리', 6, 1, '도약 6이 마무리되면서 새로운 능력이 눈에 보이기 시작해요. 손가락으로 집기(pincer grasp)가 더 정교해지고, ''마마'', ''다다''에 의미를 담기 시작합니다. 도약 후 아기가 더 활발하고 독립적으로 탐색하는 모습을 보여요.', '["집게 잡기 연습: 작은 과자(퍼프)나 안전한 소품 집기로 소근육 발달","두 물건 두드리기 놀이: 각기 다른 소리 나는 두 물건 두드리기","도약 후 수면 루틴 재정립: 도약이 끝난 후 취침 시간과 루틴을 일관되게 재정립하는 기회"]', '이 주 정기 접종 없음.', '도약 6이 끝나면 2~4주 내 수면이 안정되는 경우가 많아요. 이 안정기를 활용해 분리수면 루틴을 강화하세요.'),
  (24, 'weekly', 9, 39, '생후 39주 (9개월 3주)', NULL, 1, '혼자 서기 시간이 점점 길어지고, 한 손으로만 가구를 잡고 반쯤 서 있는 것이 가능해져요. ''안 돼''라는 말을 이해하고 잠시 멈추는 반응을 보입니다. 이유식 3회 규칙적인 패턴이 수면 리듬 안정에 도움이 됩니다.', '["서기 균형 연습: 양손을 잡아주다 한 손만 지지해 균형 훈련","간단한 \u0027와서 줘\u0027 지시 게임: 인지 발달 자극 + 이동 에너지 소모","이유식 3회 패턴 고정: 식사 시간 규칙성이 수면 리듬 안정화에 직접 기여"]', '이 주 정기 접종 없음.', '9개월은 분리불안이 가장 강한 피크 시기예요. 취침 거부가 심하더라도 짧고 일관된 루틴 후 방을 나오는 방식을 유지하세요.'),
  (25, 'weekly', 10, 40, '생후 40주 (10개월)', NULL, 1, '이 시기 아기는 가구 없이 혼자 잠깐 서기를 시도해요. 손가락으로 음식을 집어 먹는 핑거푸드가 가능해지고, 어른 행동을 따라 하기 시작합니다. 수면 퇴행이 마무리되는 시기로 서서히 안정을 찾을 수 있어요.', '["핑거푸드 식사: 스스로 집어 먹으며 소근육과 자립심 동시 발달","전화기 모방 놀이: 장난감 전화기를 귀에 대는 흉내, 모방 능력 자극","취침 시간 오후 7~7:30 목표: 10개월부터 Overtired 방지를 위한 취침 시간 엄수"]', '이 주 정기 접종 없음.', '8~10개월 수면 퇴행이 마무리되는 시기예요. 분리수면 일관성을 2~3주 유지하셨다면 이 시기부터 효과가 나타나기 시작합니다.'),
  (26, 'weekly', 10, 41, '생후 41주 (10개월 1주)', NULL, 0, '혼자 서기가 익숙해지며 첫 발걸음을 시도하는 아기도 있어요. ''이리 와'', ''앉아'' 같은 단순한 지시를 이해합니다. 낮잠 패턴이 2회에서 1회로 전환 조짐을 보이는 아기도 나타나기 시작해요.', '["걷기 유도 놀이: 양손을 잡고 걷다가 천천히 놓아주기","공 차기 연습: 서 있는 자세에서 공 차기로 균형과 하체 발달","낮잠 패턴 관찰: 오후 낮잠을 거부하기 시작하면 오전 낮잠 시간을 조금 늘릴 준비"]', '이 주 정기 접종 없음.', '혼자 걷기가 시작되면 잠시 수면이 다시 불안해질 수 있어요. 새로운 운동 능력은 뇌가 밤에도 연습하기 때문입니다. 루틴을 유지하면 1~2주 내 안정됩니다.'),
  (27, 'weekly', 10, 42, '생후 42주 (10개월 2주)', NULL, 0, '아기가 가리키는 손가락을 따라 시선을 이동하고, 원하는 것을 손가락으로 가리켜 요청합니다. 동물 소리(멍멍, 음매)를 흉내 내는 아기도 있어요. 취침 시간이 오후 7시 이전으로 당겨지는 것이 자연스럽습니다.', '["동물 소리 그림책: 동물 이름과 소리를 연결, 취침 전 루틴 책 읽기에 적합","가리키기 응답 게임: 아기가 가리키는 것을 함께 탐색, 공동 주의집중 발달","취침 루틴 20~25분 고정: 책 2~3권 읽기 + 자장가로 루틴 완성"]', '이 주 정기 접종 없음.', '10개월에 분리수면을 아직 시작 안 하셨다면 지금도 좋습니다. 다만 9개월 분리불안 피크가 지나가는 시기라 6개월보다 조금 더 오래 걸릴 수 있어요.'),
  (28, 'weekly', 10, 43, '생후 43주 (10개월 3주)', NULL, 0, '장난감 보여주기, 함께 놀자는 사회적 행동이 나타나요. ''바이바이'' 손 흔들기를 모방하고, 간단한 책의 그림을 집어서 보기 시작합니다. 수면 총량이 11~14시간 수준으로 안정되는 시기예요.', '["사회적 놀이 확장: 다른 아이와 나란히 놀기 경험 (평행 놀이 준비)","두꺼운 보드북 책 읽기: 스스로 넘기는 경험으로 취침 루틴에 자율성 추가","취침 전 \u0027오늘 고마워\u0027 인형 인사: 감사·마무리 의식으로 하루 정리"]', '이 주 정기 접종 없음. 다음 정기 접종: 12~15개월 (MMR, 수두, Hib 4차, PCV 4차, A형간염 1차, 일본뇌염 1차).', '꾸준한 루틴 유지가 이 진전을 이어가는 핵심입니다.'),
  (29, 'weekly', 11, 44, '생후 44주 (11개월)', NULL, 0, '첫 걸음마를 시작하는 아기가 많아지는 시기예요. 한 두 발 걷다 넘어지는 것을 반복하며 배웁니다. 첫 단어(마마, 다다 외)가 나오기 시작하고, ''안 돼''를 말하면 잠시 멈추는 이해력이 생겨요.', '["걷기 장애물 코스: 낮은 쿠션 넘기, 좁은 통로 통과로 균형 훈련","공 굴리기 왕복: 마주 앉아 공 굴리기로 협응력과 사회성 발달","취침 오후 7시 목표 유지: 걷기 배우는 시기는 에너지 소모가 크므로 Overtired 방지 중요"]', '이 주 정기 접종 없음.', '걷기가 시작되면 일시적으로 수면이 다시 분절될 수 있어요. 대근육 발달로 인한 자연스러운 현상입니다. 기존 루틴을 유지하면 1~2주 내 안정됩니다.'),
  (30, 'weekly', 11, 45, '생후 45주 (11개월 1주) ★원더윅스 도약 7 시작', 7, 0, '원더윅스 도약 7(순서의 세계)이 시작돼요. 아기가 ''이것 다음에 저것이 온다''는 순서와 절차를 이해하기 시작합니다. 장난감을 제대로 된 순서로 쌓거나, 그릇에 뚜껑을 닫으려는 시도가 나타나요.', '["순서 있는 쌓기 놀이: 컵 쌓기, 링 끼우기 등 순서가 있는 장난감 탐색","뚜껑 열고 닫기: 간단한 통·뚜껑 조작으로 순서 이해와 소근육 발달","취침 루틴 순서 카드 (선택): 목욕→책→자장가 순서를 그림으로 보여주며 예측 가능성 제공"]', '이 주 정기 접종 없음.', '도약 7 중 예측 가능한 루틴이 더욱 중요해져요. 취침 순서를 항상 같게 유지하는 것이 도약 중 안정감을 주는 핵심입니다.'),
  (31, 'weekly', 11, 46, '생후 46주 (약 11개월) ★원더윅스 도약 7 피크', 7, 0, '도약 7 피크예요. 아기가 간단한 지시를 두 단계로 이해하기 시작합니다(''공 가져다가 상자에 넣어''). 흉내 내기 능력이 급격히 발달해 부모의 행동을 즉각 따라 해요. 걸음마가 더 능숙해집니다.', '["두 단계 심부름 놀이: \u0027공 가져와\u0027 → \u0027통에 넣어\u0027처럼 두 단계 지시 게임","청소 흉내 놀이: 장난감 빗자루로 쓸기, 수건으로 닦기 모방 활동","취침 전 정리 의식: 장난감을 함께 정리하며 \u0027놀이 끝 → 잘 시간\u0027 신호 확립"]', '이 주 정기 접종 없음.', '도약 7 중 예측 가능성에 대한 욕구가 강해집니다. 취침 루틴이 흔들리지 않도록 두 부모가 같은 방식으로 일관되게 진행해주세요.'),
  (32, 'weekly', 11, 47, '생후 47주 (11개월 3주) ★원더윅스 도약 7 마무리', 7, 0, '도약 7이 마무리되면서 아기가 간단한 문제를 스스로 해결하려는 모습을 보여요. 컵에서 물을 마시는 방법, 문을 여는 방법을 탐색합니다. ''마마'', ''다다'' 외에 의미 있는 단어가 1~3개 생기기 시작해요.', '["간단한 문제 해결 탐색: 뚜껑 있는 컵, 여닫히는 작은 상자 등 스스로 해결 탐색 유도","음악 리듬 놀이: 드럼처럼 두드리기, 흔들며 박자 맞추기","취침 전 오늘의 이야기: 오늘 있었던 일을 짧게 이야기해주며 하루 마무리 루틴"]', '이 주 정기 접종 없음. 12개월 접종 준비: MMR 1차, 수두 1차, Hib 4차, PCV 4차, A형간염 1차, 일본뇌염 1차.', '도약 7 후 수면이 안정되면 분리수면 진전이 느껴질 거예요. 이 시기 안정기를 활용해 밤잠 분리수면을 완전히 자리잡게 해주세요.'),
  (33, 'weekly', 11, 48, '생후 48주 (11개월 4주)', NULL, 0, '12개월이 코앞입니다. 걸음마가 많이 능숙해지고, 짧은 거리를 달리기 시작하는 아기도 있어요. 단어를 2~3개 이상 말하고, 낮 동안의 낮잠이 1회로 줄어들기 시작하는 아기가 나타납니다.', '["공원 걷기·뛰기: 안전한 야외에서 자유롭게 걷고 뛰며 충분한 에너지 소모","블록 쌓고 무너뜨리기: 손-눈 협응과 인과관계 탐색","12개월 접종 예약 확인: 생후 12~15개월 사이 접종 예약"]', '이 주 정기 접종 없음. 12개월 접종(MMR 1차, 수두 1차 등) 예약을 진행해주세요.', '11개월은 분리수면을 완성해가는 시기예요. 아직 시작 못 하셨다면 늦었다고 생각 마세요. 12개월 이후에도 충분히 가능합니다.'),
  (34, 'weekly', 12, 49, '생후 49주 (12개월)', NULL, 0, '생후 12개월에 접어든 아기는 혼자 걷거나 걷기 직전이고, 의미 있는 첫 단어를 말합니다. 낮잠이 2회에서 1회로 전환되기 시작하는 시기로, 낮잠 거부와 밤잠 분절로 보이는 12개월 수면 퇴행이 시작될 수 있어요.', '["자유 보행 탐색: 안전한 실내에서 자유롭게 걷고 탐색할 수 있는 공간 확보","단어 그림책 읽기: 그림을 보며 단어를 말해보는 언어 발달 활동, 취침 전 루틴에 적합","낮잠 전환 대비: 오후 낮잠 거부 시 취침 시간 30분 당기기로 Overtired 방지"]', '이달 국가필수예방접종: MMR(홍역·유행성이하선염·풍진) 1차, 수두(VAR) 1차, Hib(뇌수막염) 4차(마지막), PCV(폐렴구균) 4차(마지막), A형간염 1차, 일본뇌염(불활성화) 1차. 한 번에 많은 접종이 필요하니 소아과와 일정 협의를 권장합니다.', '12개월은 분리수면을 시작하기에 아직 늦지 않아요. 걷기 시작과 함께 독립심이 생기는 시기라 오히려 수면 독립에 도움이 될 수 있습니다.'),
  (35, 'weekly', 12, 50, '생후 50주 (12개월 1주)', NULL, 1, '12개월 수면 퇴행이 진행 중일 수 있어요. 걷기 시작과 낮잠 전환(2→1회)이 겹쳐 수면이 분절되기 쉽습니다. 낮잠을 거부하거나 밤잠이 잦아진다면 낮잠 스케줄을 조정할 필요가 있어요.', '["낮잠 전환 대응: 2회 낮잠을 오후 1회(오후 12:30~1시)로 통합 시도","낮 충분한 야외 활동: 걷기·뛰기로 에너지 충분히 소모","취침 시간 당기기: 낮잠 1회로 줄면 취침 오후 6:30~7시로 앞당기기"]', '이 주 정기 접종 없음. 12개월 접종을 아직 못 받으셨다면 이번 주 소아과 방문을 권장합니다.', '12개월 퇴행 중에는 새로운 수면 교육법 시작보다 기존 루틴 유지가 우선이에요. 낮잠 전환이 자리잡히면 수면이 안정됩니다.'),
  (36, 'weekly', 12, 51, '생후 51주 (12개월 3주)', NULL, 1, '걷기가 더 안정적으로 발달하고, 어른이 하는 행동(청소, 전화 통화)을 정교하게 모방해요. 한 단어에 여러 의미를 담는 ''한 단어 문장''이 활발해집니다. 낮잠 전환이 진행 중이라면 밤잠 시간이 길어지는 것이 정상이에요.', '["모방 역할 놀이: 전화기, 빗자루, 숟가락 등 어른 도구 모방 활동","야외 자연 탐색 산책: 나뭇잎, 돌, 꽃 관찰로 감각 자극 + 보행 에너지 소모","낮잠 1회 패턴 안착: 오전 낮잠 없애고 오후 1시 낮잠 1회 고정 시도"]', '이 주 정기 접종 없음.', '낮잠이 1회로 줄어들면 야간 수면이 더 길고 깊어질 수 있어요. 이 변화를 분리수면 강화의 기회로 삼아보세요.'),
  (37, 'weekly', 12, 52, '생후 52주 (12개월 4주)', NULL, 0, '아기가 혼자 걷고, 앉아 있다가 스스로 일어서며 자유롭게 이동해요. ''마마'', ''다다'' 외에 2~4개 의미 있는 단어를 사용하고, 원하는 것을 손가락으로 가리키며 요청합니다. 낮잠이 1회로 정착하기 시작하는 아기가 많아요.', '["걷기·뛰기 자유 시간: 충분한 이동 활동으로 야간 수면 깊이 확보","그림책 스스로 넘기기: 책장 넘기기 소근육 발달 + 취침 전 루틴 자율성","낮잠 1회 완전 안착: 오후 1~2시 낮잠 1회 루틴 고정"]', '이 주 정기 접종 없음. 12~15개월 사이 접종(MMR, 수두 등)을 아직 못 받으셨다면 15개월 전에 완료해주세요.', '12개월이 지나면 분리수면이 더 안정되는 경우가 많아요. 독립적으로 움직이는 능력이 생기면서 자기만의 공간에 대한 수용도도 함께 높아집니다.'),
  (38, 'monthly', 13, NULL, '생후 13개월 ★원더윅스 도약 8', 8, 0, '원더윅스 도약 8(프로그램의 세계)이 시작되는 시기예요. 아기가 목표를 달성하기 위한 여러 단계 계획을 세우기 시작합니다. 의자를 밀어 놓고 그 위에 올라서서 높은 곳의 물건을 잡는 문제 해결이 가능해져요. 걷기가 더 안정적이고, 뛰기 시작하는 아기도 생깁니다.', '["문제 해결 탐색: 간단한 퍼즐, 넣고 빼기 장난감으로 \u0027계획-실행\u0027 능력 자극","공원 자유 탐색 30분: 걷기·오르기·내려오기로 대근육 에너지 충분히 소모","취침 전 책 선택권: 아기가 책 1권을 직접 선택하게 해 자율성 만족"]', '12~15개월 접종 기간입니다. MMR 1차, 수두 1차, Hib 4차, PCV 4차, A형간염 1차, 일본뇌염 1차를 아직 받지 않으셨다면 이달 소아과 방문을 권장합니다.', '도약 8로 수면이 일시적으로 불안해질 수 있어요. 도약 중에는 새 방법 시작보다 기존 루틴 유지가 우선입니다. 도약 후(1~3주) 안정기를 활용하세요.'),
  (39, 'monthly', 14, NULL, '생후 14개월', NULL, 0, '뛰기가 가능해지고, 계단을 기어오르는 아기가 많아져요. 어휘가 10~20개 정도로 늘고, 원하는 것을 단어와 제스처를 함께 사용해 표현합니다. 낮잠은 1회(오후 1~2시간)로 완전히 안착되는 시기예요.', '["계단 오르기 연습 (안전 감독): 한 발씩 오르며 협응력과 하체 발달","소꿉놀이 시작: 컵에 물 따르기, 그릇에 담기 등 역할 놀이로 인지 발달","낮잠 1회 패턴 유지: 오후 낮잠 후 취침까지 4~5시간 각성 창 지키기"]', '이 달 정기 접종 없음. 12~15개월 접종을 아직 완료 못 하셨다면 다음 달(15개월) 전에 완료해주세요.', '14개월은 분리수면이 꽤 안정되는 시기예요. 야간에 스스로 다시 잠드는 횟수가 늘었다면 잘 진행되고 있는 증거입니다.'),
  (40, 'monthly', 15, NULL, '생후 15개월 ★원더윅스 도약 9', 9, 0, '원더윅스 도약 9(원칙의 세계)가 시작돼요. ''공평하다'', ''규칙'', ''내 것·네 것'' 같은 원칙 개념이 발달합니다. 이 시기부터 ''안 돼''에 더 강하게 반항하거나 경계를 테스트하는 행동이 늘어요. 어휘가 3~5개, 그림 보고 이름 말하기 가능.', '["간단한 규칙 있는 게임: \u0027공 굴려주면 나도 굴린다\u0027 같은 상호 규칙 게임","블록 함께 쌓기: 협력 놀이의 첫 단계, 사회성과 집중력 발달","취침 규칙 일관성 강화: 도약으로 경계 테스트가 늘어나는 이 시기 \u0027잘 시간은 정해진 것\u0027 원칙 유지"]', '12~15개월 접종 마감 시기입니다. MMR 1차, 수두 1차, Hib 4차, PCV 4차, A형간염 1차, 일본뇌염 1차를 아직 받지 않으셨다면 이달 내 완료하세요.', '도약 9로 경계 테스트가 늘어 취침 거부가 강해질 수 있어요. ''잠자리에 들면 나온다''는 규칙을 흔들리지 않게 유지하는 것이 핵심입니다.'),
  (41, 'monthly', 16, NULL, '생후 16개월', NULL, 0, '뛰기가 안정되고, 공을 발로 차거나 낮은 물건을 타고 오르는 것이 가능해져요. 어휘가 빠르게 늘어 20~50개 단어를 이해하고, 그 중 일부를 표현합니다. 두 가지 물건의 이름을 함께 말해주면 해당 물건을 동시에 가져오는 이해력이 생겨요.', '["공 차기: 서 있는 자세에서 공 차기, 균형감·협응력 발달","그림 명칭 게임: 그림책에서 \u0027강아지 어디 있어?\u0027 찾기, 어휘 폭발기에 맞춤 자극","취침 전 몸 흔들기 노래: 느린 리듬의 자장가에 맞춰 안기며 이완"]', '이 달 정기 접종 없음.', '16개월은 독립심이 강해지는 시기예요. 분리수면 루틴을 아이가 예측할 수 있도록 항상 같은 순서로 진행해주세요.'),
  (42, 'monthly', 17, NULL, '생후 17개월 ★원더윅스 도약 10', 10, 0, '원더윅스 도약 10(시스템의 세계)이 이 시기 전후로 나타나요. 복잡한 구조와 시스템을 이해하기 시작하며 소꿉놀이가 정교해지고, 인형을 ''아기처럼'' 돌보는 역할 놀이가 발달합니다. 이것이 마지막 원더윅스 도약이에요.', '["인형 재우기 놀이: 인형에게 이불 덮고 자장가 불러주기, 수면 루틴을 놀이로 학습","소꿉놀이 세트: 요리하기, 그릇 나르기 등 복잡한 역할 놀이 시작","취침 전 인형 함께 재우기: \u0027우리 모두 잘 시간\u0027 의식으로 수면 수용성↑"]', '이 달 정기 접종 없음. 다음 달(18개월) 접종 예약 준비: DTaP 4차, A형간염 2차.', '마지막 원더윅스 도약이 마무리되면 수면이 전반적으로 더 안정되어요. 이후로는 발달 도약보다 일상 루틴이 수면 질을 결정하는 더 큰 요소가 됩니다.'),
  (43, 'monthly', 18, NULL, '생후 18개월', NULL, 1, '이 시기 아기는 혼자 잘 걷고 뛰며, 끄적이기(크레용 낙서)가 가능해요. 어휘가 급격히 증가하는 ''언어 폭발기''가 시작되며, ''싫어'', ''내 거'', ''더''와 같은 주장 표현이 늘어납니다. 독립심이 높아지면서 취침 거부가 강해지는 18개월 수면 퇴행이 나타날 수 있어요.', '["크레용 낙서 놀이: 큰 종이에 자유롭게 끄적이기, 창의적 표현 + 소근육 발달","야외 뛰기·오르기: 정글짐, 미끄럼틀 등 충분한 신체 활동으로 취침 전 에너지 소모","취침 루틴에 선택권 부여: \u0027이 책 읽을까, 저 책 읽을까?\u0027 2지선다로 통제감 제공"]', '이달 국가필수예방접종: DTaP(디프테리아·파상풍·백일해) 4차 추가접종, A형간염 2차(1차 후 6개월 이상). 소아과 방문 시 일본뇌염 2차(1차 후 1개월 이상)도 확인하세요.', '18개월은 언어 폭발 + 독립심 충돌로 ''싫어''와 함께 취침 거부가 강해지는 시기예요. 선택권을 주면서도 ''잘 시간은 바꿀 수 없다''는 일관성을 유지하세요. 퇴행 중 새 방법 시도는 삼가고 기존 루틴 유지를 권장합니다.'),
  (44, 'monthly', 19, NULL, '생후 19개월', NULL, 0, '어휘가 폭발적으로 늘어 50~100개 단어를 표현해요. 두세 단어를 조합하기 시작하고, 간단한 질문에 ''응/아니''로 답할 수 있습니다. 계단을 발을 교대로 올라가거나 혼자 의자에 오르내리는 것이 가능해요.', '["말 따라 하기 게임: 간단한 단어나 소리를 번갈아 말하는 에코 게임","계단 오르내리기 연습: 난간 잡고 한 발씩 계단 오르기, 하체 발달","취침 전 오늘의 하이라이트 대화: \u0027오늘 뭐가 제일 좋았어?\u0027 짧은 대화로 하루 감정 정리"]', '이 달 정기 접종 없음. 일본뇌염 불활성화 2차 접종 시기 확인 (1차 후 1개월 이상).', '18개월 퇴행이 마무리되면서 수면이 안정되기 시작해요. 취침 루틴을 아이와 함께 이야기하며 ''자기 전에 우리가 하는 것''으로 의미 부여하는 것이 도움이 됩니다.'),
  (45, 'monthly', 20, NULL, '생후 20개월', NULL, 0, '두 단어 문장이 안정되고 ''엄마 물'', ''아빠 와'' 같은 표현이 자연스러워요. 달리기와 공 차기가 능숙해지고, 블록 4~6개를 쌓을 수 있어요. 소꿉놀이에서 역할이 더 구체화됩니다.', '["블록 높이 쌓기 경쟁: 얼마나 높이 쌓을 수 있는지 도전, 집중력·협응력 발달","역할 놀이 (가게, 병원): 다양한 역할 경험으로 사회성·언어 발달","취침 전 낮 활동 정리 대화: \u0027오늘 공원에서 뭐 했지?\u0027 회상 대화로 기억력·언어 동시 자극"]', '이 달 정기 접종 없음.', '20개월이면 분리수면이 대부분 안정되어요. 가끔 야간 각성이 있더라도 스스로 다시 잠들 수 있다면 잘 진행되고 있는 것입니다.'),
  (46, 'monthly', 21, NULL, '생후 21개월', NULL, 0, '표현 어휘가 100개 이상으로 늘고, ''나'', ''내가'', ''우리'' 같은 대명사를 사용하기 시작해요. 발끝으로 서기, 두 발 점프가 가능해집니다. ''내 것''에 대한 소유 개념이 강해지며 다른 아이와의 갈등이 생기기 시작해요.', '["두 발 점프 놀이: 낮은 단 위에서 뛰어내리기, 대근육 발달 + 에너지 소모","스티커 붙이기: 소근육 발달 + 집중력, 취침 전 진정 활동에 적합","취침 전 부드러운 음악 시간: 잔잔한 음악 10분으로 전환 의식"]', '이 달 정기 접종 없음.', '소유 개념이 강해지면서 ''내 침대'', ''내 공간''에 대한 수용도가 높아질 수 있어요. 아이 방을 아이가 좋아하는 것들로 꾸며 수면 공간에 대한 긍정적 연상을 만들어주세요.'),
  (47, 'monthly', 22, NULL, '생후 22개월', NULL, 0, '세 단어 문장이 등장하고, 색 이름 1~2가지를 말할 수 있어요. 계단을 발을 교대로 올라가고, 뚜껑을 돌려서 열 수 있어요. 상상력 놀이가 더 풍부해지며 ''가상의 친구''나 ''상상의 음식'' 등 추상적 역할 놀이가 나타납니다.', '["색 탐색 놀이: \u0027빨간 것 찾아봐\u0027 게임으로 색 인식 발달","가상 요리 놀이: 상상 재료로 요리하는 흉내, 창의성·언어 발달","취침 전 상상 여행: \u0027오늘 꿈에서 어디 갈까?\u0027 짧은 상상 이야기로 취침 기대감 형성"]', '이 달 정기 접종 없음.', '상상력이 발달하면서 취침 시 무서움을 느끼기 시작할 수 있어요. 작은 수면 등(나이트라이트)을 허용하고, 취침 전 안심 이야기를 들려주는 것이 도움됩니다.'),
  (48, 'monthly', 23, NULL, '생후 23개월', NULL, 0, '만 2세를 앞두고 어휘, 운동, 사회성이 모두 급격히 발달하는 시기예요. 다른 아이 옆에서 비슷한 놀이를 하는 ''평행 놀이''가 활발하고, ''왜?''라는 질문이 시작됩니다. 낮잠은 1회가 고정되며 밤잠이 10~11시간으로 안정돼요.', '["평행 놀이 경험: 다른 아이 옆에서 비슷한 활동, 사회성 발달 + 자연스러운 에너지 소모","대형 도화지 핑거페인팅: 손 전체를 사용하는 감각 활동, 창의적 표현","취침 전 오늘의 이야기 3가지: \u0027오늘 좋았던 것 3가지\u0027 말해보기, 긍정 감정 마무리"]', '이 달 정기 접종 없음. 24개월 접종(일본뇌염 3차) 예약을 준비하세요.', '만 2세에 가까워지면서 취침 거부가 다시 강해지는 아기도 있어요. ''왜 자야 해?''라는 질문에 간단명료하게 답하고, 루틴 일관성을 지키는 것이 가장 효과적입니다.'),
  (49, 'monthly', 24, NULL, '생후 24개월 (만 2세)', NULL, 1, '생후 24개월. 두 단어 문장으로 소통하고, 달리기·계단 오르기·공 차기가 능숙해요. ''내 것''에 대한 강한 집착과 함께 상상력 발달로 악몽이나 취침 두려움이 시작될 수 있는 24개월 수면 퇴행 시기입니다. 다른 사람의 감정에 공감하기 시작해요.', '["야외 뛰기·자전거: 충분한 야외 신체 활동으로 취침 전 에너지 충분히 소모","역할 놀이 (병원, 마트): 하루 경험을 놀이로 정리해 불안 감소","취침 전 안심 루틴 강화: 수면 등 + 애착 인형 + 일관된 자장가로 안도감 형성"]', '이달 국가필수예방접종: 일본뇌염 불활성화 3차(2차 후 12개월 이상). 소아과에서 접종 기록 확인 후 진행하세요.', '24개월 수면 퇴행 중 악몽과 취침 두려움이 시작될 수 있어요. ''침대는 안전한 곳''이라는 인식을 강화하고, 수면 등·애착 인형을 활용하세요. 취침 전 낮에 있었던 걱정을 이야기해주는 것이 도움이 됩니다.'),
  (50, 'monthly', 25, NULL, '생후 25개월', NULL, 0, '세 단어 이상 문장으로 소통하고, 색 이름 2~3가지를 말할 수 있어요. 계단을 혼자 오르내리고, 두 발 점프가 능숙해집니다. ''나'', ''너'', ''우리'' 대명사를 자연스럽게 사용하며 사회적 놀이가 더 풍부해져요.', '["모래놀이: 파고 쌓고 붓는 촉감 놀이로 감각 발달 + 집중력","색 이름 맞추기 게임: 주변 물건 색 맞추기로 인지 발달 자극","취침 전 감사 나누기: \u0027오늘 고마웠던 것\u0027 1가지씩 말하며 긍정 감정 마무리"]', '이 달 정기 접종 없음. 인플루엔자는 매년 10~11월 접종 권장.', '25개월은 분리수면이 대부분 안정적인 시기예요. 야간에 가끔 깨더라도 스스로 다시 잠들 수 있게 기다려주세요.'),
  (51, 'monthly', 26, NULL, '생후 26개월', NULL, 0, '상상력 놀이가 매우 풍부해지며 ''가상의 친구''가 생기는 아기도 있어요. ''왜''라는 질문이 폭발적으로 늘고, 간단한 원인-결과를 이해합니다. 퍼즐 4~6조각을 맞출 수 있고, 가위를 처음 사용해볼 수 있어요.', '["간단한 퍼즐 맞추기: 4~6조각 퍼즐로 집중력·공간 인지 발달","역할 놀이 확장: 가상 여행, 우주선 타기 등 상상력 풍부한 놀이","취침 전 상상 이야기: 아이가 주인공인 짧은 이야기를 함께 만들며 취침 기대감 형성"]', '이 달 정기 접종 없음.', '이 시기 취침 시 ''무서운 것이 있어''라고 하는 아이가 있어요. 괴물은 없다고 확인시켜 주되, 아이의 두려움을 무시하지 말고 공감해주세요. 취침 전 방 확인 의식이 도움됩니다.'),
  (52, 'monthly', 27, NULL, '생후 27개월', NULL, 0, '세 단어 이상 문장이 유창해지고, 짧은 이야기를 이해하며 질문에 답할 수 있어요. 달리기가 능숙해지고 공을 던지고 받기가 가능해집니다. 낮잠이 줄어들기 시작하는 아기도 있고, 아직 1회 낮잠이 필요한 아기도 있어요.', '["공 주고받기: 두 손으로 잡기·던지기, 눈-손 협응 발달","블록 집 만들기: 벽과 지붕이 있는 구조물 만들기, 공간 인지 발달","낮잠 유무 파악: 낮잠 없어도 오후에 기분 좋으면 낮잠 전환 중. 취침 시간 30분 앞당기기"]', '이 달 정기 접종 없음.', '낮잠이 줄어드는 시기에 취침 거부가 강해질 수 있어요. 낮잠을 안 자도 ''조용한 휴식 시간(quiet time)''을 30~60분 확보하면 저녁까지 에너지가 유지됩니다.'),
  (53, 'monthly', 28, NULL, '생후 28개월', NULL, 0, '네 단어 이상 문장을 구사하고, ''오늘'', ''어제'', ''내일''의 시간 개념이 생기기 시작해요. 가위질·핑거페인팅 등 미술 활동이 더 정교해집니다. 친구와 함께 놀이를 조율하기 시작하는 협력 놀이의 초기 단계예요.', '["시간 개념 놀이: \u0027어제 뭐 했지?\u0027, \u0027내일 뭐 할까?\u0027 대화로 시간 개념 발달","협력 쌓기: 두 사람이 함께 타워 쌓기, 사회성·소통 발달","취침 전 내일 기대 이야기: \u0027내일 뭐가 제일 기대돼?\u0027 대화로 취침을 \u0027내일에 대한 준비\u0027로 프레이밍"]', '이 달 정기 접종 없음.', '시간 개념이 생기기 시작하면 ''잠자면 내일이 와''라는 말이 효과적인 취침 동기부여가 될 수 있어요.'),
  (54, 'monthly', 29, NULL, '생후 29개월', NULL, 0, '대부분의 문장에서 조사와 어미가 비교적 자연스럽게 사용되기 시작해요. 세발자전거 타기를 시도하는 아기도 있고, 혼자 옷 벗기가 가능해집니다. 자기 통제가 조금씩 생기지만 감정 폭발(tantrum)은 여전히 흔한 시기예요.', '["세발자전거 타기: 발로 구르거나 발 붙이고 앉기 연습, 균형·협응력 발달","감정 카드 놀이: 기쁨·슬픔·화남 표정 카드 보며 감정 어휘 발달","취침 전 감정 확인: \u0027오늘 화났던 거 있어?\u0027 짧은 감정 대화로 취침 전 감정 해소"]', '이 달 정기 접종 없음.', '감정 폭발이 많은 날은 취침도 어렵게 느껴질 수 있어요. 취침 30분 전부터 조용하고 예측 가능한 루틴으로 전환해주세요.'),
  (55, 'monthly', 30, NULL, '생후 30개월 (만 2세 6개월)', NULL, 0, '표현 어휘가 300개 이상이고, ''나는 ~가 좋아''처럼 선호를 표현해요. 두 발 점프·공 차기가 능숙하고, 두 단계 지시를 따릅니다. 다른 아이와 함께 놀기 시작하며 공유 개념이 조금씩 발달해요. 낮잠 없이 하루를 보낼 수 있는 아기가 많아집니다.', '["두 단계 심부름: \u0027냉장고에서 물 꺼내서 엄마한테 줘\u0027처럼 두 단계 지시 게임","모래·물 감각 놀이: 무거운 감각 자극(heavy work)으로 신경계 조절","낮잠 없는 날 취침 시간 조정: 낮잠 없는 날은 오후 6:30~7시 취침 목표"]', '이 달 정기 접종 없음.', '낮잠이 없어지면 저녁에 Overtired가 되기 쉬워요. 이 시기는 취침 시간을 평소보다 30~60분 일찍 잡는 것이 중요합니다.'),
  (56, 'monthly', 31, NULL, '생후 31개월', NULL, 0, '글자·숫자에 관심을 보이는 아기도 생겨요. 친구의 이름을 부르고 함께 역할을 나누는 협동 놀이가 가능해집니다. 질문이 매우 많아지고, 이야기를 만들어내는 서사 능력이 발달해요.', '["이야기 만들기 놀이: \u0027왕자가 어디 갔을까?\u0027 함께 이야기 이어가기","협동 퍼즐: 함께 큰 퍼즐 완성하기, 협력과 집중력 발달","취침 전 오늘의 책 3줄 요약: 오늘 읽은 책 이야기를 아이가 직접 요약하게 하기"]', '이 달 정기 접종 없음.', '이 시기 아이는 취침 거부 이유가 더 구체적이에요(''물 마시고 싶어'', ''화장실 가고 싶어''). 루틴 안에 물 마시기·화장실 가기를 미리 포함해 핑계 거리를 없애주세요.'),
  (57, 'monthly', 32, NULL, '생후 32개월', NULL, 0, '혼자 옷을 입으려 시도하고, 지퍼를 올리거나 단추 채우기를 연습해요. 문장이 점점 복잡해지며 ''왜냐하면'', ''그런데'' 같은 접속사를 사용하기 시작합니다. 규칙이 있는 간단한 보드게임을 즐길 수 있어요.', '["옷 입기 연습: 단추·지퍼 연습으로 소근육 발달 + 자립심 강화","간단한 보드게임: 차례 지키기, 규칙 따르기 훈련","취침 준비 스스로 하기: 잠옷 입기, 이 닦기를 스스로 하며 자립심 + 취침 루틴 내재화"]', '이 달 정기 접종 없음.', '이 시기부터 ''나는 무서운 거 없어''라고 스스로 말하며 자신감을 키울 수 있어요. 취침 시 아이의 용기를 칭찬해주세요.'),
  (58, 'monthly', 33, NULL, '생후 33개월', NULL, 0, '그림을 그릴 때 사람을 동그라미와 선으로 표현하기 시작해요. 비슷한 또래 친구와 규칙 있는 놀이를 즐기고, 차례를 기다리는 능력이 발달합니다. 낮잠 없이 생활하는 날이 많아지고, 밤잠이 10~12시간으로 충분해져요.', '["사람 그리기: 동그라미 머리, 선 몸통 그리기 — 창의적 표현 발달","차례 지키기 게임: 순서대로 탑 쌓기, 사회성 발달","취침 전 오늘 그림 한 장: 오늘 있었던 일을 간단히 그려 하루 마무리 의식"]', '이 달 정기 접종 없음.', '낮잠 없는 날이 늘면 저녁 취침이 일찍 잡혀야 해요. 오후 7시 이전 취침이 자연스러운 시기입니다.'),
  (59, 'monthly', 34, NULL, '생후 34개월', NULL, 0, '어휘가 매우 풍부해지고, 짧은 이야기를 처음부터 끝까지 스스로 이야기할 수 있어요. 한 발로 균형 잡기를 연습하고, 세발자전거를 능숙하게 탑니다. 친구와의 갈등을 말로 해결하려는 시도가 나타나요.', '["한 발 균형 잡기: 바닥에 그린 선 위 한 발로 서기, 균형감 발달","이야기 릴레이: 번갈아 이야기 한 문장씩 이어가기, 창의성·언어 발달","취침 전 내일 준비 함께하기: 내일 입을 옷 고르기 등 내일을 준비하며 취침을 긍정적으로 연상"]', '이 달 정기 접종 없음.', '이 시기 아이는 자기 침대에서 자는 것을 자랑스럽게 여기기 시작할 수 있어요. ''○○는 이제 자기 침대에서 잘 수 있어''라고 자주 칭찬해주세요.'),
  (60, 'monthly', 35, NULL, '생후 35개월', NULL, 0, '대화가 자연스럽고 문장이 길어져요. 어른과 두세 번 이상 주고받는 대화가 가능합니다. ''ㄱ'', ''ㄴ'' 같은 글자 이름에 관심을 보이고, 한두 글자를 따라 쓰는 아이도 나타나요. 낮잠은 대부분 필요 없고 밤잠 11~12시간이 안정됩니다.', '["글자 이름 카드: 자기 이름 첫 글자 찾기 — 한글 관심 발달","자연 탐험 산책: 돌·나뭇잎·벌레 관찰하며 자연 호기심 자극","취침 전 \u0027내가 가장 잘하는 것\u0027 이야기: 자기 긍정감 형성으로 안정적인 수면 준비"]', '이 달 정기 접종 없음. 36개월 이후 4~6세 DTaP 5차, IPV 4차, MMR 2차, 수두 2차 예정.', '35개월이면 분리수면이 완전히 안정된 아이가 대부분이에요. 만약 아직 어려움이 있다면 소아과 혹은 수면 전문가 상담을 고려해보세요.'),
  (61, 'monthly', 36, NULL, '생후 36개월 (만 3세)', NULL, 0, '생후 36개월. 이 시기 아이는 자기 이름과 나이를 말하고, 어른과 자연스럽게 대화를 주고받습니다. 혼자 옷을 입고, 포크를 사용하며, 구슬을 실에 꿸 수 있어요. 친구들과 함께 노는 것을 즐기고, 헤어질 때 10분 내 안정을 찾아요. 밤잠 10~12시간이 완전히 안정됩니다.', '["구슬 꿰기·끈 잇기: 소근육 집중 활동, 성취감 발달","친구와 함께 하는 야외 놀이: 뛰기·오르기·협력 게임으로 충분한 에너지 소모","취침 전 오늘의 감사 일기: 오늘 고마웠던 것 1~2가지 이야기로 긍정적 하루 마무리"]', '이 달 정기 접종 없음. 이후 4~6세 접종: DTaP 5차, IPV 4차, MMR 2차(미접종 시), 수두 2차(미접종 시).', '만 3세가 되면 분리수면은 완전히 자리잡은 아이가 대부분이에요. 자기 침대·자기 방에서 자는 것이 자연스러운 일상이 됩니다. 수면 독립이 완전히 자리잡은 시기입니다.')
ON DUPLICATE KEY UPDATE id=id;
